import React,{useEffect,useMemo,useState}from"react";
import{createRoot}from"react-dom/client";
import{LayoutDashboard,Building2,Plus,Search,Mail,Phone,Pencil,Trash2,Target,CheckCircle2,X,Download,Upload,Users,GraduationCap,Wallet,Image as ImageIcon,Copy,Check,CalendarClock,MessageSquareText,UserRound,FileImage,ShieldCheck,Printer,UserPlus,Network,History,LockKeyhole,MessagesSquare,LifeBuoy,Inbox,Send,UserCheck}from"lucide-react";
import"./styles.css";
import{AGREEMENT_VERSION,agreementSections,printableAgreementHtml}from"./agreement";
import{api}from"./api";
import{playbookTutorial,salesSituations,salesScripts,package399,businessRules}from"./playbook";

const statuses=["NEW","MOCKUP READY","CONTACTED","REPLIED","INTERESTED","READY FOR TOM","MEETING","INVOICE SENT","DEPOSIT PAID","IN DEVELOPMENT","WON","LOST"];
const labels={"NEW":"Jauns","MOCKUP READY":"Mockup gatavs","CONTACTED":"Sazināts","REPLIED":"Atbildēja","INTERESTED":"Interesējas","READY FOR TOM":"Gatavs pārņemšanai","MEETING":"Google Meet","INVOICE SENT":"Rēķins nosūtīts","DEPOSIT PAID":"Priekšapmaksa","IN DEVELOPMENT":"Izstrādē","WON":"Pabeigts","LOST":"Zaudēts"};
const industries=["Autoserviss","Būvniecība","Viesu nams","Skaistumkopšana","Zobārstniecība","Restorāns","Pakalpojumi","Cits"];
const payoutStatuses=["DEPOSIT PAID","IN DEVELOPMENT","WON"];
const baseMembers=[
{id:"admin",name:"Toms",email:"",role:"admin",parentId:null,payout:0,override:0,agreementAcceptedAt:"2026-09-22T00:00:00.000Z",agreementVersion:AGREEMENT_VERSION,paperSigned:true,active:true},
{id:"lead1",name:"Mārtiņš",email:"martins@example.com",role:"team_lead",parentId:"admin",payout:50,override:10,agreementAcceptedAt:null,agreementVersion:null,paperSigned:false,active:true},
{id:"m2",name:"Anna",email:"anna@example.com",role:"sales",parentId:"lead1",payout:50,override:0,agreementAcceptedAt:null,agreementVersion:null,paperSigned:false,active:true}
];
const emptyLead={company:"",industry:"Autoserviss",city:"",website:"",email:"",phone:"",score:50,status:"NEW",value:399,notes:"",handoffSummary:"",promises:"",lastContact:"",nextFollowUp:"",ownerId:"",commission:null,commissionPaid:false,mockupImage:"",inactiveDays:0,contactLog:[],adminComments:[]};
const seed=[
{id:"1",company:"Cēsis Auto Serviss",industry:"Autoserviss",city:"Cēsis",website:"https://example.com",email:"info@cesisauto.lv",phone:"+371 20000001",score:82,status:"MOCKUP READY",value:399,notes:"Novecojis dizains, vājš mobile UX.",lastContact:"",nextFollowUp:"",ownerId:"lead1",commission:null,commissionPaid:false,mockupImage:"",contactLog:[]},
{id:"2",company:"Vidzemes Motors",industry:"Autoserviss",city:"Valmiera",website:"",email:"serviss@vidzemesmotors.lv",phone:"+371 20000002",score:91,status:"CONTACTED",value:399,notes:"Nav savas mājaslapas.",lastContact:"2026-09-20",nextFollowUp:"2026-09-24",ownerId:"m2",commission:null,commissionPaid:false,mockupImage:"",contactLog:[{id:"c1",date:"2026-09-20",type:"E-pasts",note:"Nosūtīts pirmais piedāvājums un mockup."}]},
{id:"3",company:"AutoFix Riga",industry:"Autoserviss",city:"Rīga",website:"https://autofix.example",email:"info@autofix.lv",phone:"+371 20000003",score:76,status:"DEPOSIT PAID",value:399,notes:"Klients apstiprināja standarta lapu.",lastContact:"2026-09-21",nextFollowUp:"",ownerId:"m2",commission:null,commissionPaid:false,mockupImage:"",contactLog:[{id:"c2",date:"2026-09-21",type:"E-pasts",note:"Saņemta priekšapmaksa."}]}
];
const now=()=>new Date().toISOString();
function roleName(r){return r==="admin"?"Admin":r==="team_lead"?"Team Lead":"Sales Partner"}
function normMember(m){return{parentId:"admin",payout:50,override:0,agreementAcceptedAt:null,agreementVersion:null,paperSigned:false,active:true,...m}}
function normLead(l){return{...emptyLead,...l,contactLog:Array.isArray(l.contactLog)?l.contactLog:[],adminComments:Array.isArray(l.adminComments)?l.adminComments:[]}}
function domain(v=""){try{return new URL(v.startsWith("http")?v:"https://"+v).hostname.replace(/^www\./,"").toLowerCase()}catch{return v.toLowerCase().replace(/^www\./,"").split("/")[0]}}
function printAgreement(member){const w=window.open("","_blank","width=900,height=1000");if(!w)return alert("Pārlūks nobloķēja drukas logu.");w.document.open();w.document.write(printableAgreementHtml(member));w.document.close()}

function App({sessionUser,onLogout}){
 const[members,setMembers]=useState([normMember(sessionUser)]);
 const[leads,setLeads]=useState([]);
 const[audit,setAudit]=useState(()=>{try{return JSON.parse(localStorage.getItem("tagorit_audit"))||[]}catch{return[]}});
 const[messages,setMessages]=useState([]);
 const[support,setSupport]=useState([]);
 const[active,setActive]=useState(sessionUser.id);
 const[backendLoading,setBackendLoading]=useState(true),[backendError,setBackendError]=useState("");
 const[view,setView]=useState("dashboard"),[query,setQuery]=useState(""),[status,setStatus]=useState("ALL"),[modal,setModal]=useState(null),[memberModal,setMemberModal]=useState(null),[agreementMember,setAgreementMember]=useState(null),[copied,setCopied]=useState("");
 useEffect(()=>{let alive=true;Promise.all([api.bootstrap(),api.messages(),api.support()]).then(([d,m,t])=>{if(!alive)return;setMembers((d.users||[]).map(normMember));setLeads((d.leads||[]).map(normLead));setMessages(m.messages||[]);setSupport(t.tickets||[]);setActive(d.user.id);setBackendLoading(false)}).catch(e=>{if(!alive)return;setBackendError(e.message);setBackendLoading(false)});return()=>{alive=false}},[]);

 useEffect(()=>localStorage.setItem("tagorit_audit",JSON.stringify(audit)),[audit]);


 const user=members.find(m=>m.id===active)||members[0],isAdmin=user.role==="admin",isLead=user.role==="team_lead";
 const childIds=members.filter(m=>m.parentId===user.id&&m.active).map(m=>m.id);
 const visible=isAdmin?leads:isLead?leads.filter(l=>l.ownerId===user.id||childIds.includes(l.ownerId)):leads.filter(l=>l.ownerId===user.id);
 const filtered=visible.filter(l=>(l.company+" "+l.city+" "+l.email+" "+l.industry).toLowerCase().includes(query.toLowerCase())&&(status==="ALL"||l.status===status));
 const sellerLockedStatuses=["READY FOR TOM","MEETING","INVOICE SENT","DEPOSIT PAID","IN DEVELOPMENT","WON"];
 const log=(action,detail,actorId=active)=>setAudit(v=>[{id:crypto.randomUUID(),at:now(),actorId,action,detail},...v].slice(0,500));
 const eligible=visible.filter(l=>payoutStatuses.includes(l.status));
 const ownCommission=eligible.filter(l=>l.ownerId===user.id).reduce((a,l)=>a+Number(l.commission??user.payout??0),0);
 const overrideCommission=isLead?eligible.filter(l=>childIds.includes(l.ownerId)).reduce((a)=>a+Number(user.override||0),0):0;
 const adminPayout=isAdmin?leads.filter(l=>payoutStatuses.includes(l.status)).reduce((a,l)=>{const owner=members.find(m=>m.id===l.ownerId);const base=Number(l.commission??owner?.payout??0),lead=members.find(m=>m.id===owner?.parentId&&m.role==="team_lead");return a+base+Number(lead?.override||0)},0):0;
 const earned=isAdmin?adminPayout:ownCommission+overrideCommission;
 const paid=isAdmin?0:eligible.filter(l=>l.ownerId===user.id&&l.commissionPaid).reduce((a,l)=>a+Number(l.commission??user.payout??0),0);
 const stats={total:visible.length,contacted:visible.filter(l=>["CONTACTED","REPLIED","INTERESTED","MEETING","DEPOSIT PAID","IN DEVELOPMENT","WON"].includes(l.status)).length,hot:visible.filter(l=>["INTERESTED","MEETING"].includes(l.status)).length,deals:eligible.length,revenue:eligible.reduce((a,l)=>a+Number(l.value||0),0),earned,paid,pending:isAdmin?earned:Math.max(0,earned-paid)};

 async function saveLead(e){
  e.preventDefault();
  const x=normLead(modal);
  const duplicate=leads.find(l=>l.id!==x.id&&((x.website&&domain(x.website)===domain(l.website))||(x.email&&l.email&&x.email.toLowerCase()===l.email.toLowerCase())||(x.company&&l.company&&x.company.trim().toLowerCase()===l.company.trim().toLowerCase())));
  if(duplicate)return alert("Šis uzņēmums jau ir sistēmā: "+duplicate.company+". Tas pieder citam vai jau esošam klienta ierakstam.");
  try{
   if(x.id){const d=await api.updateLead(x);setLeads(v=>v.map(l=>l.id===x.id?normLead(d.lead):l));log("Klients atjaunināts",x.company)}
   else{const d=await api.createLead({...x,ownerId:x.ownerId||active});setLeads(v=>[normLead(d.lead),...v]);log("Klients pievienots",d.lead.company)}
   setModal(null);
  }catch(err){alert(err.message)}

 }
 async function changeStatus(id,statusValue){const l=leads.find(x=>x.id===id);if(!l)return;try{const d=await api.updateLead({...l,status:statusValue});setLeads(v=>v.map(x=>x.id===id?normLead(d.lead):x));log("Statuss mainīts",(l.company||id)+" → "+labels[statusValue])}catch(err){alert(err.message)}}
 async function removeLead(id){const l=leads.find(x=>x.id===id);if(!confirm("Dzēst šo klientu?"))return;try{await api.deleteLead(id);setLeads(v=>v.filter(x=>x.id!==id));log("Klients dzēsts",l?.company||id)}catch(err){alert(err.message)}}
 async function claimInactive(id){const l=leads.find(x=>x.id===id);if(!l)return;if(!confirm("Pārņemt šo lead, jo tam vismaz 14 dienas nav aktivitātes?"))return;try{const d=await api.updateLead({id,action:"CLAIM_INACTIVE"});setLeads(v=>v.map(x=>x.id===id?normLead(d.lead):x));log("Neaktīvs lead pārņemts",l.company)}catch(err){alert(err.message)}}
 async function saveMember(data){
  try{
   if(data.id){
    const d=await api.updateUser(data);const m=normMember(d.user);setMembers(v=>v.map(x=>x.id===m.id?m:x));log("Komandas dalībnieks atjaunināts",m.name);
   }else{
    const d=await api.createUser(data);const m=normMember(d.user);setMembers(v=>[...v,m]);log("Komandas dalībnieks pievienots",m.name);alert("Pagaidu parole "+m.name+": "+d.tempPassword+"\n\nSaglabā to droši un nosūti darbiniekam atsevišķi. Vienošanās viņam parādīsies pirmajā ielogošanās reizē.");
   }
   setMemberModal(null);
  }catch(err){alert(err.message)}
 }
 async function acceptAgreement(memberId){
  try{
   const d=await api.acceptAgreement(AGREEMENT_VERSION);
   setMembers(v=>v.map(m=>m.id===memberId?normMember(d.user):m));
   log("Digitālā vienošanās apstiprināta","Versija "+AGREEMENT_VERSION,memberId);
   setAgreementMember(null);
  }catch(err){alert(err.message)}
 }
 async function togglePaper(id){const m=members.find(x=>x.id===id);if(!m)return;try{const d=await api.updateUser({...m,paperSigned:!m.paperSigned});setMembers(v=>v.map(x=>x.id===id?normMember(d.user):x));log("Papīra līguma statuss mainīts",m.name)}catch(err){alert(err.message)}}
 function exportData(){const b=new Blob([JSON.stringify({members,leads,audit},null,2)],{type:"application/json"}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download="tagorit-backup.json";a.click();URL.revokeObjectURL(u)}
 function importData(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(Array.isArray(d.leads))setLeads(d.leads.map(normLead));if(Array.isArray(d.members))setMembers(d.members.map(normMember));if(Array.isArray(d.audit))setAudit(d.audit)}catch{alert("Nederīgs backup fails.")}};r.readAsText(f)}

 const agreementRequired=!isAdmin&&(!user.agreementAcceptedAt||user.agreementVersion!==AGREEMENT_VERSION);
 const title={dashboard:isAdmin?"Komandas pārskats":isLead?"Manas komandas pārskats":"Mans pārskats",leads:"Klienti",tutorial:"Darba instrukcija",scripts:"Sarunu skripti",team:"Komanda",messages:"Privātās ziņas",support:"Supports",handoff:"Pārņemšana",audit:"Audit log"}[view];

 if(backendLoading)return <div className="appLoading"><div className="mark">T</div><b>Ielādē Tagorit...</b></div>;
 if(backendError)return <div className="fatal"><h2>Nevar pieslēgties Tagorit backendam</h2><p>{backendError}</p><button className="secondary" onClick={onLogout}>Atgriezties uz login</button></div>;
 return <div className="shell">
  <aside><div className="brand"><div className="mark">T</div><div><b>Tagorit</b><small>Sales network</small></div></div>
   <div className="accountBox"><div className="avatar">{user.name?.slice(0,1).toUpperCase()}</div><div><b>{user.name}</b><small>{roleName(user.role)}</small></div><button onClick={onLogout}>Iziet</button></div>
   <nav><N icon={LayoutDashboard} a={view==="dashboard"} on={()=>setView("dashboard")}>Dashboard</N><N icon={Building2} a={view==="leads"} on={()=>setView("leads")}>Klienti</N><N icon={GraduationCap} a={view==="tutorial"} on={()=>setView("tutorial")}>Tutorial</N><N icon={MessageSquareText} a={view==="scripts"} on={()=>setView("scripts")}>Skripti</N><N icon={MessagesSquare} a={view==="messages"} on={()=>setView("messages")}>Ziņas</N><N icon={LifeBuoy} a={view==="support"} on={()=>setView("support")}>Supports</N>{isAdmin&&<N icon={Inbox} a={view==="handoff"} on={()=>setView("handoff")}>Pārņemšana</N>}{isAdmin&&<N icon={Network} a={view==="team"} on={()=>setView("team")}>Komanda</N>}{isAdmin&&<N icon={History} a={view==="audit"} on={()=>setView("audit")}>Audit</N>}</nav>
   <div className="goal"><Target size={18}/><div><b>Dienas mērķis</b><small>10–15 kvalitatīvi kontakti</small></div></div>
  </aside>
  <main><header><div><h1>{title}</h1><p>{isAdmin?"Visa komanda, klienti, vienošanās un komisijas vienuviet.":isLead?"Tavi klienti, tava komanda un override komisijas.":"Tavi klienti, process un nopelnītā nauda."}</p></div><div className="actions">{isAdmin&&<><button className="square" onClick={exportData}><Download size={17}/></button><label className="square"><Upload size={17}/><input hidden type="file" accept="application/json" onChange={importData}/></label></>}{["dashboard","leads"].includes(view)&&<button className="primary" onClick={()=>setModal({...emptyLead,ownerId:isAdmin?(members.find(m=>m.role==="sales"&&m.active)?.id||""):active})}><Plus size={16}/>Pievienot klientu</button>}</div></header>
   {view==="dashboard"&&<Dashboard stats={stats} leads={visible} members={members} edit={setModal} isAdmin={isAdmin} isLead={isLead} user={user} childIds={childIds}/>}
   {view==="leads"&&<Leads leads={filtered} members={members} query={query} setQuery={setQuery} status={status} setStatus={setStatus} edit={setModal} remove={removeLead} update={changeStatus} isAdmin={isAdmin} isLead={isLead} user={user} claimInactive={claimInactive}/>}
   {view==="tutorial"&&<Tutorial isAdmin={isAdmin}/>}
   {view==="scripts"&&<Scripts copied={copied} setCopied={setCopied} isAdmin={isAdmin}/>}
   {view==="messages"&&<Messages user={user} members={members} messages={messages} setMessages={setMessages} isAdmin={isAdmin}/>}
   {view==="support"&&<Support user={user} members={members} tickets={support} setTickets={setSupport} isAdmin={isAdmin}/>}
   {view==="handoff"&&isAdmin&&<Handoff leads={leads} members={members} update={changeStatus} edit={setModal}/>}
   {view==="team"&&isAdmin&&<Team members={members} leads={leads} edit={setMemberModal} add={()=>setMemberModal({name:"",email:"",role:"sales",parentId:"admin",payout:50,override:0,active:true})} togglePaper={togglePaper}/>}
   {view==="audit"&&isAdmin&&<Audit audit={audit} members={members}/>}
  </main>
  {modal&&<LeadModal lead={modal} setLead={setModal} members={members} isAdmin={isAdmin} save={saveLead} close={()=>setModal(null)}/>}
  {memberModal&&<MemberModal member={memberModal} members={members} save={saveMember} close={()=>setMemberModal(null)}/>}
  {agreementMember&&<AgreementModal member={members.find(m=>m.id===agreementMember.id)||agreementMember} accept={acceptAgreement} close={()=>setAgreementMember(null)} adminMode/>}
  {agreementRequired&&<AgreementModal member={user} accept={acceptAgreement} gate onBack={()=>setActive("admin")}/>}
 </div>
}

function N({icon:Icon,a,on,children}){return <button className={a?"active":""} onClick={on}><Icon size={18}/>{children}</button>}
function Card({icon:Icon,label,value,note}){return <div className="card"><div className="cardIcon"><Icon size={19}/></div><div><small>{label}</small><b>{value}</b><span>{note}</span></div></div>}
function Dashboard({stats,leads,members,edit,isAdmin,isLead,user,childIds}){return <div className="content">
 <div className="cards"><Card icon={Building2} label="Klienti" value={stats.total} note="Redzamais klientu loks"/><Card icon={Mail} label="Kontaktēti" value={stats.contacted} note="Saziņa sākta"/><Card icon={Target} label="Interesējas" value={stats.hot} note="Silti klienti / Meet"/><Card icon={CheckCircle2} label="Darījumi" value={stats.deals} note={isAdmin?"€"+stats.revenue+" apgrozījums":"Ar priekšapmaksu"}/></div>
 <div className="earnings"><div><Wallet size={20}/><span><b>{isAdmin?"Komandas komisiju saistības":isLead?"Mana komisija + override":"Mana atlīdzība"}</b><small>{isLead?"Override €"+user.override+" par tiešā apakšpartnera klientu.":"Skaitās pēc klienta priekšapmaksas."}</small></span></div><div className="money"><span>Nopelnīts<b>€{stats.earned}</b></span>{!isAdmin&&<><span>Izmaksāts<b>€{stats.paid}</b></span><span>Gaida<b>€{stats.pending}</b></span></>}</div></div>
 {isLead&&<div className="teamMini">{members.filter(m=>childIds.includes(m.id)).map(m=><div key={m.id}><div className="avatar">{m.name.slice(0,1)}</div><span><b>{m.name}</b><small>{leads.filter(l=>l.ownerId===m.id).length} klienti · {leads.filter(l=>l.ownerId===m.id&&payoutStatuses.includes(l.status)).length} darījumi</small></span></div>)}</div>}
 <div className="grid"><section className="panel"><div className="panelHead"><div><h2>Sales pipeline</h2><p>Kur šobrīd atrodas klienti</p></div></div><div className="pipeline">{statuses.filter(s=>s!=="LOST").map(s=><div className="bar" key={s}><span>{labels[s]}</span><div><i style={{width:(leads.length?Math.max(3,Math.round(leads.filter(l=>l.status===s).length/leads.length*100)):0)+"%"}}/></div><b>{leads.filter(l=>l.status===s).length}</b></div>)}</div></section>
 <section className="panel"><div className="panelHead"><div><h2>Jaunākie klienti</h2><p>Atver, lai turpinātu darbu</p></div></div>{leads.slice(0,6).map(l=>{const o=members.find(m=>m.id===l.ownerId);return <button className="recent" key={l.id} onClick={()=>edit({...l})}><span>{l.company.slice(0,2).toUpperCase()}</span><div><b>{l.company}</b><small>{labels[l.status]} · {o?.name||"—"}</small></div></button>})}</section></div>
 </div>}
function Leads({leads,members,query,setQuery,status,setStatus,edit,remove,update,isAdmin,isLead,user,claimInactive}){
 const sellerStatuses=["NEW","MOCKUP READY","CONTACTED","REPLIED","INTERESTED","READY FOR TOM","LOST"];
 return <div className="content"><div className="filters"><div className="search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Meklēt uzņēmumu..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">Visi statusi</option>{statuses.map(s=><option key={s} value={s}>{labels[s]}</option>)}</select><span>{leads.length} rezultāti</span></div><div className="panel tableWrap"><table><thead><tr><th>Uzņēmums</th><th>Atbildīgais</th><th>Statuss</th><th>Mockup</th><th>Kontakti</th><th>Follow-up</th><th>Vērtība</th><th></th></tr></thead><tbody>{leads.map(l=>{const o=members.find(m=>m.id===l.ownerId),locked=!isAdmin&&["READY FOR TOM","MEETING","INVOICE SENT","DEPOSIT PAID","IN DEVELOPMENT","WON"].includes(l.status),canClaim=isLead&&l.ownerId!==user.id&&Number(l.inactiveDays||0)>=14&&!locked&&l.status!=="LOST";return <tr key={l.id}><td><button className="company" onClick={()=>edit({...l})}><i>{l.company.slice(0,2).toUpperCase()}</i><div><b>{l.company}</b><small>{l.industry} · {l.city||"—"} · Score {l.score}{Number(l.inactiveDays||0)>=14?" · "+l.inactiveDays+" d. bez aktivitātes":""}</small></div></button></td><td><span className="pill"><UserRound size={12}/>{o?.name||"—"}</span></td><td><select className="status" disabled={locked} value={l.status} onChange={e=>update(l.id,e.target.value)}>{(isAdmin?statuses:Array.from(new Set([...sellerStatuses,l.status]))).map(s=><option key={s} value={s}>{labels[s]||s}</option>)}</select></td><td>{l.mockupImage?<button className="thumb" onClick={()=>edit({...l})}><img src={l.mockupImage}/><span>Skatīt</span></button>:<span className="muted">Nav</span>}</td><td><div className="contact">{l.email&&<a href={"mailto:"+l.email}><Mail size={14}/></a>}{l.phone&&<a href={"tel:"+l.phone}><Phone size={14}/></a>}</div></td><td>{l.nextFollowUp?<span className="pill"><CalendarClock size={12}/>{l.nextFollowUp}</span>:<span className="muted">—</span>}</td><td><b>€{l.value}</b></td><td><div className="rowActions">{canClaim&&<button title="Pārņemt pēc 14 d. neaktivitātes" onClick={()=>claimInactive(l.id)}><UserCheck size={14}/></button>}<button onClick={()=>edit({...l})}><Pencil size={14}/></button><button className="danger" onClick={()=>remove(l.id)} disabled={locked}><Trash2 size={14}/></button></div></td></tr>})}</tbody></table>{!leads.length&&<div className="empty">Nav klientu.</div>}</div></div>
}
function Tutorial({isAdmin}){
 const[search,setSearch]=useState(""),[open,setOpen]=useState(playbookTutorial[0]?.id||""),[situationCat,setSituationCat]=useState("ALL");
 const q=search.trim().toLowerCase();
 const modules=playbookTutorial.filter(m=>!q||(m.title+" "+m.stage+" "+m.summary+" "+m.bullets.join(" ")).toLowerCase().includes(q));
 const allowedSituations=isAdmin?salesSituations:salesSituations.filter(x=>!["DEPOSIT PAID","IN DEVELOPMENT","WON"].includes(x.status));
 const cats=["ALL",...Array.from(new Set(allowedSituations.map(x=>x.cat)))];
 const situations=allowedSituations.filter(x=>(situationCat==="ALL"||x.cat===situationCat)&&(!q||(x.title+" "+x.what+" "+x.do.join(" ")+" "+x.dont.join(" ")).toLowerCase().includes(q)));
 return <div className="content playbookPage">
  <div className="intro playbookIntro"><div><span className="eyebrow">TAGORIT SALES PLAYBOOK</span><h2>No pirmā lead līdz apmaksātam klientam</h2><p>Šī ir darba rokasgrāmata ikdienai. Ja neesi pārliecināts, ko darīt konkrētā situācijā, vispirms atrodi to šeit; ja jautājums ir par custom cenu, tehnisku funkciju vai nestandarta vienošanos — nodod Tomam.</p></div><div className="priceBox"><small>Standarta piedāvājums</small><b>399 €</b><span>50% priekšapmaksa · 2 labojumu cikli</span></div></div>
  <section className="panel packageScope"><div className="sectionHeading"><div><span className="eyebrow">399 € PAKETE — NOFIKSĒTS</span><h2>Ko tieši drīkst pārdot par fiksēto cenu</h2></div><strong>€{package399.price}</strong></div><div className="packageCols"><div><h4>Ietilpst</h4>{package399.includes.map(x=><p key={x}><Check size={13}/>{x}</p>)}<p><Check size={13}/>{package399.pages}</p><p><Check size={13}/>{package399.language}</p></div><div><h4>Neietilpst</h4>{package399.excludes.map(x=><p key={x}><X size={13}/>{x}</p>)}</div></div><div className="scopeNotes"><p><b>Saturs:</b> {package399.contentRule}</p><p><b>Termiņš:</b> {package399.timeline}</p></div></section>
  <section className="panel rulesStrip"><div><b>Lead īpašumtiesības</b><p>{businessRules.leadOwnership} {businessRules.inactivity}</p></div><div><b>Komisija</b><p>{businessRules.commission} {businessRules.override} {businessRules.payouts}</p></div><div><b>Rēķins</b><p>{businessRules.invoice}</p></div></section>
  <div className="handoffBoundary"><div className="boundaryIcon"><UserCheck size={20}/></div><div><small>SVARĪGĀKĀ DARBA ROBEŽA</small><h3>Partnera darbs beidzas pie saņemtas priekšapmaksas.</h3><p>Līdz priekšapmaksai tu atrodi klientu, uzrunā, kvalificē, atbildi uz iebildumiem un noved līdz darījumam. Tiklīdz Toms apstiprina maksājumu, visu tālāko — materiālus, izstrādi, labojumus, atlikumu, publicēšanu un uzturēšanu — pārņem Toms.</p></div><span>DEPOSIT PAID → STOP</span></div>
  <div className="playbookTools"><div className="search playbookSearch"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Meklē: atlaide, e-veikals, follow-up, priekšapmaksa..."/></div><div className="quickRules"><span><CheckCircle2 size={13}/>Komisija tikai pēc priekšapmaksas</span><span><UserCheck size={13}/>Custom → Toms</span><span><ShieldCheck size={13}/>Nesoli to, ko neesi saskaņojis</span></div></div>
  <section className="playbookSection">
   <div className="sectionHeading"><div><span className="eyebrow">DARBA PROCESS</span><h2>{playbookTutorial.length} soļi, kuri jāzina katram partnerim</h2></div><span>{modules.length} sadaļas</span></div>
   <div className="moduleList">{modules.map((m,i)=><article className={"playModule "+(open===m.id?"open":"")} key={m.id}>
    <button className="moduleHead" onClick={()=>setOpen(open===m.id?"":m.id)}><div className="moduleNo">{String(i+1).padStart(2,"0")}</div><div><small>{m.stage}</small><h3>{m.title}</h3><p>{m.summary}</p></div><span className="moduleToggle">{open===m.id?"−":"+"}</span></button>
    {open===m.id&&<div className="moduleBody">
      <div className="moduleCols"><div><h4>Ko darīt</h4><ul>{m.bullets.map((x,j)=><li key={j}>{x}</li>)}</ul></div><div><h4>Pārbaudi pirms ej tālāk</h4><div className="checklist">{m.checklist.map((x,j)=><span key={j}><Check size={13}/>{x}</span>)}</div><div className="statusGuide"><small>Ieteicamais statuss</small><b>{labels[m.status]||m.status}</b></div></div></div>
      <div className="playAction"><b>Nākamā darbība</b><p>{m.action}</p></div>
      <div className="avoidBox"><b>Ko nedarīt</b>{m.avoid.map((x,j)=><p key={j}>• {x}</p>)}</div>
    </div>}
   </article>)}</div>
  </section>
  <section className="playbookSection">
   <div className="sectionHeading"><div><span className="eyebrow">SITUĀCIJU BIBLIOTĒKA</span><h2>Ko darīt, ja klients saka...</h2><p>Ātra palīdzība tipiskām situācijām. Meklē pēc frāzes vai izvēlies kategoriju.</p></div><span>{situations.length} situācijas</span></div>
   <div className="catBar">{cats.map(c=><button key={c} className={situationCat===c?"active":""} onClick={()=>setSituationCat(c)}>{c==="ALL"?"Visas":c}</button>)}</div>
   <div className="situationGrid">{situations.map((x,i)=><article className="panel situationCard" key={x.title+i}><div className="situationTop"><span>{x.cat}</span><b>{labels[x.status]||x.status}</b></div><h3>{x.title}</h3><p className="situationWhat">{x.what}</p><div className="dosDonts"><div><h4><CheckCircle2 size={13}/>Dari</h4>{x.do.map((v,j)=><p key={j}>• {v}</p>)}</div><div><h4><X size={13}/>Nedari</h4>{x.dont.map((v,j)=><p key={j}>• {v}</p>)}</div></div></article>)}</div>
  </section>
  <div className="two playbookBottom"><section className="panel padded"><h3>Ko drīkst solīt pats</h3><ul><li>Standarta uzņēmuma mājaslapa par 399 €</li><li>Responsīvs dizains</li><li>Esošā satura pārnešana</li><li>Kontaktforma un pamata SEO</li><li>Publicēšana un 2 labojumu cikli</li><li>Orientējoši 3–7 darba dienas pēc materiālu un priekšapmaksas saņemšanas</li></ul></section><section className="panel padded dangerPanel"><h3>Kad obligāti iesaistīt Tomu</h3><ul><li>E-veikals / WooCommerce</li><li>Booking / rezervācijas sistēmas</li><li>Online maksājumi</li><li>Lietotāju konti / datubāze</li><li>API / ārējās integrācijas</li><li>Custom kalkulatori vai sistēmas</li><li>Nestandarta cena, atlaide vai termiņš</li><li>Jebkas, par ko neesi pārliecināts</li></ul></section></div>
 </div>
}

function Scripts({copied,setCopied,isAdmin}){
 const[search,setSearch]=useState(""),[cat,setCat]=useState("ALL");
 const visibleScripts=isAdmin?salesScripts:salesScripts.filter(x=>!["Materiāli","Labojumi","Launch","Maintenance","Priekšapmaksa","Rēķins"].includes(x.cat));
 const cats=["ALL",...Array.from(new Set(visibleScripts.map(x=>x.cat)))];
 const q=search.trim().toLowerCase();
 const items=visibleScripts.filter(x=>(cat==="ALL"||x.cat===cat)&&(!q||(x.title+" "+x.subject+" "+x.when+" "+x.text).toLowerCase().includes(q)));
 function cp(i,t){navigator.clipboard?.writeText(t);setCopied(i);setTimeout(()=>setCopied(""),1200)}
 return <div className="content scriptsPage">
  <div className="intro scriptsIntro"><div><span className="eyebrow">GATAVĀS SAGATAVES</span><h2>Skripti gandrīz katrai pārdošanas situācijai</h2><p>Nekopē akli. Pielāgo uzņēmuma nosaukumu, konkrēto situāciju un to, ko klients jau ir pateicis. Skripts ir drošs pamats, nevis robots.</p></div><div className="scriptCount"><b>{visibleScripts.length}</b><span>gatavas sagataves</span></div></div>
  <div className="scriptToolbar"><div className="search playbookSearch"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Meklē skriptu..."/></div><div className="catBar scriptCats">{cats.map(c=><button key={c} className={cat===c?"active":""} onClick={()=>setCat(c)}>{c==="ALL"?"Visi":c}</button>)}</div></div>
  <div className="scriptGrid detailedScripts">{items.map((x,i)=>{const key=x.title+i;return <section className="panel script detailedScript" key={key}><div className="scriptTop"><div><span className="eyebrow">{x.cat}</span><h2>{x.title}</h2></div><button className="secondary" onClick={()=>cp(key,"Temats: "+x.subject+"\n\n"+x.text)}>{copied===key?<><Check size={14}/>Nokopēts</>:<><Copy size={14}/>Kopēt</>}</button></div><div className="scriptMeta"><div><small>Kad izmantot</small><p>{x.when}</p></div><div><small>Temats</small><p>{x.subject}</p></div></div><pre>{x.text}</pre><div className="scriptNext"><CheckCircle2 size={14}/><div><small>Pēc nosūtīšanas</small><b>{x.next}</b></div></div></section>})}</div>
  {!items.length&&<div className="empty">Nekas netika atrasts. Pamēģini citu meklējamo vārdu vai kategoriju.</div>}
 </div>
}
function Team({members,leads,edit,add,togglePaper}){const workers=members.filter(m=>m.role!=="admin");return <div className="content"><div className="teamHead"><div><h2>Komandas struktūra</h2><p>Team Lead var saņemt override par savu tiešo apakšpartneru apmaksātiem klientiem.</p></div><button className="primary" onClick={add}><UserPlus size={15}/>Pievienot darbinieku</button></div><div className="hierarchy panel"><div className="rootNode"><div className="avatar">T</div><div><b>Toms</b><small>Admin · redz visu sistēmu</small></div></div>{workers.map(m=>{const parent=members.find(x=>x.id===m.parentId),own=leads.filter(l=>l.ownerId===m.id),deals=own.filter(l=>payoutStatuses.includes(l.status));return <div className={"workerRow "+(m.role==="sales"?"indent":"")} key={m.id}><div className="workerMain"><div className="avatar">{m.name.slice(0,1).toUpperCase()}</div><div><b>{m.name}</b><small>{roleName(m.role)}{parent&&m.role==="sales"?" · zem "+parent.name:""}</small></div></div><div className="agreementBadges"><span className={m.agreementAcceptedAt&&m.agreementVersion===AGREEMENT_VERSION?"ok":"warn"}><ShieldCheck size={12}/>{m.agreementAcceptedAt?"Digitāli "+m.agreementVersion:"Nav apstiprināts"}</span><button className={m.paperSigned?"okBtn":"warnBtn"} onClick={()=>togglePaper(m.id)}>{m.paperSigned?"Papīrs parakstīts":"Papīrs nav parakstīts"}</button></div><div className="workerStats"><span>Klienti<b>{own.length}</b></span><span>Darījumi<b>{deals.length}</b></span><span>Komisija<b>€{m.payout}</b></span>{m.role==="team_lead"&&<span>Override<b>€{m.override}</b></span>}</div><div className="workerActions"><button onClick={()=>printAgreement(m)} title="Drukāt līgumu"><Printer size={15}/></button><button onClick={()=>edit({...m})}><Pencil size={15}/></button></div></div>})}</div></div>}
function Messages({user,members,messages,setMessages,isAdmin}){const[to,setTo]=useState(isAdmin?(members.find(m=>m.role!=="admin"&&m.active)?.id||""):(members.find(m=>m.role==="admin")?.id||"")),[body,setBody]=useState(""),[sending,setSending]=useState(false);const mine=messages.sort((a,b)=>new Date(b.at)-new Date(a.at));async function send(){if(!body.trim()||!to)return;setSending(true);try{const d=await api.sendMessage({to,body:body.trim()});setMessages(v=>[d.message,...v]);setBody("")}catch(err){alert(err.message)}finally{setSending(false)}}return <div className="content"><div className="messagesLayout"><section className="panel composer"><h2>Jauna privāta ziņa</h2><F l="Saņēmējs"><select value={to} onChange={e=>setTo(e.target.value)}>{isAdmin?members.filter(m=>m.role!=="admin"&&m.active).map(m=><option key={m.id} value={m.id}>{m.name} · {roleName(m.role)}</option>):members.filter(m=>m.role==="admin").map(m=><option key={m.id} value={m.id}>{m.name} · Admin</option>)}</select></F><F l="Ziņa"><textarea rows="6" value={body} onChange={e=>setBody(e.target.value)} placeholder="Uzraksti privātu ziņu..."/></F><button className="primary" disabled={sending} onClick={send}><Send size={15}/>{sending?"Nosūta...":"Nosūtīt"}</button></section><section className="panel inbox"><div className="panelHead"><div><h2>Ziņu vēsture</h2><p>{isAdmin?"Visa komandas komunikācija":"Tavas privātās ziņas ar adminu"}</p></div></div>{mine.length?mine.map(m=>{const from=members.find(x=>x.id===m.from),toM=members.find(x=>x.id===m.to);return <div className="messageRow" key={m.id}><div className="avatar">{(from?.name||"?").slice(0,1)}</div><div><b>{from?.name||"Sistēma"} <span>→ {toM?.name||"Admin"}</span></b><p>{m.body}</p><small>{new Date(m.at).toLocaleString("lv-LV")}</small></div></div>}):<div className="empty">Ziņu vēl nav.</div>}</section></div></div>}

function Support({user,members,tickets,setTickets,isAdmin}){const[subject,setSubject]=useState(""),[body,setBody]=useState(""),[busy,setBusy]=useState(false);async function act(data){setBusy(true);try{const d=await api.supportAction(data);setTickets(d.tickets||[])}catch(err){alert(err.message)}finally{setBusy(false)}}async function create(){if(!subject.trim()||!body.trim())return;await act({subject:subject.trim(),body:body.trim()});setSubject("");setBody("")}async function reply(id){const text=prompt("Atbilde uz support pieprasījumu:");if(!text?.trim())return;await act({action:"reply",id,body:text.trim()})}async function close(id){await act({action:"toggle",id})}return <div className="content"><div className="messagesLayout">{!isAdmin&&<section className="panel composer"><h2>Jauns support pieprasījums</h2><F l="Tēma"><input value={subject} onChange={e=>setSubject(e.target.value)} placeholder="Ar ko vajag palīdzību?"/></F><F l="Apraksts"><textarea rows="6" value={body} onChange={e=>setBody(e.target.value)} placeholder="Apraksti problēmu..."/></F><button className="primary" disabled={busy} onClick={create}><LifeBuoy size={15}/>Nosūtīt supportam</button></section>}<section className="panel inbox fullInbox"><div className="panelHead"><div><h2>{isAdmin?"Support pieprasījumi":"Mani support pieprasījumi"}</h2><p>{tickets.filter(t=>t.status==="OPEN").length} atvērti</p></div></div>{tickets.length?tickets.map(t=>{const owner=members.find(m=>m.id===t.userId);return <div className="ticket" key={t.id}><div className="ticketTop"><div><b>{t.subject}</b><small>{owner?.name||"—"} · {new Date(t.createdAt).toLocaleString("lv-LV")}</small></div><span className={t.status==="OPEN"?"ticketOpen":"ticketClosed"}>{t.status==="OPEN"?"Atvērts":"Slēgts"}</span></div><p>{t.body}</p>{(t.replies||[]).map(r=>{const from=members.find(m=>m.id===r.from);return <div className="ticketReply" key={r.id}><b>{from?.name||"Admin"}</b><span>{r.body}</span></div>})}<div className="ticketActions"><button className="secondary" disabled={busy} onClick={()=>reply(t.id)}>Atbildēt</button>{isAdmin&&<button className="secondary" disabled={busy} onClick={()=>close(t.id)}>{t.status==="OPEN"?"Aizvērt":"Atvērt"}</button>}</div></div>}):<div className="empty">Support pieprasījumu nav.</div>}</section></div></div>}

function Handoff({leads,members,update,edit}){
 const active=leads.filter(l=>["READY FOR TOM","MEETING","INVOICE SENT"].includes(l.status));
 return <div className="content"><div className="handoffHero"><UserCheck size={22}/><div><h2>Klienti pirms apmaksas</h2><p>Jebkurš klients pirms maksājuma nonāk pie tevis. Tu pārbaudi scope, vajadzības gadījumā sarunā Meet un rēķinu izsūti manuāli.</p></div><b>{active.length}</b></div><div className="panel handoffList">{active.length?active.map(l=>{const owner=members.find(m=>m.id===l.ownerId);return <div className="handoffRow" key={l.id}><div className="avatar">{l.company.slice(0,1)}</div><div className="handoffInfo"><b>{l.company}</b><small>{owner?.name||"—"} · {l.email||l.phone||"Nav kontakta"} · {labels[l.status]}</small><p><b>Prasības:</b> {l.handoffSummary||"Nav kopsavilkuma."}</p><p><b>Apsolīts:</b> {l.promises||"Nav norādīts."}</p></div><div className="handoffActions"><button className="secondary" onClick={()=>edit({...l})}>Atvērt</button>{l.status==="READY FOR TOM"&&<><button className="secondary" onClick={()=>update(l.id,"MEETING")}>Google Meet</button><button className="primary" onClick={()=>update(l.id,"INVOICE SENT")}>Rēķins nosūtīts</button></>}{l.status==="MEETING"&&<button className="primary" onClick={()=>update(l.id,"INVOICE SENT")}>Rēķins nosūtīts</button>}{l.status==="INVOICE SENT"&&<button className="primary" onClick={()=>update(l.id,"DEPOSIT PAID")}><CheckCircle2 size={14}/>Priekšapmaksa saņemta</button>}</div></div>}):<div className="empty">Šobrīd nav klientu, kuri gaida tavu darbību pirms apmaksas.</div>}</div></div>
}

function Audit({audit,members}){return <div className="content"><div className="panel auditList">{audit.length?audit.map(a=>{const m=members.find(x=>x.id===a.actorId);return <div className="auditRow" key={a.id}><History size={15}/><div><b>{a.action}</b><p>{a.detail}</p></div><span>{m?.name||"Sistēma"} · {new Date(a.at).toLocaleString("lv-LV")}</span></div>}):<div className="empty">Audit ierakstu vēl nav.</div>}</div></div>}
function MemberModal({member,members,save,close}){const[m,setM]=useState(normMember(member));const set=(k,v)=>setM({...m,[k]:v});const teamLeads=members.filter(x=>x.role==="team_lead"&&x.active&&x.id!==m.id);return <div className="overlay"><form className="modal smallModal" onSubmit={e=>{e.preventDefault();if(!m.name.trim())return;save(m)}}><div className="modalHead"><div><h2>{m.id?"Rediģēt darbinieku":"Jauns darbinieks"}</h2><p>Pēc izveides jaunajam cilvēkam būs jāapstiprina sadarbības vienošanās.</p></div><button type="button" onClick={close}><X/></button></div><div className="modalBody"><div className="form"><F l="Vārds, uzvārds"><input required value={m.name} onChange={e=>set("name",e.target.value)}/></F><F l="E-pasts"><input type="email" required value={m.email||""} onChange={e=>set("email",e.target.value)}/></F><F l="Loma"><select value={m.role} onChange={e=>set("role",e.target.value)}><option value="sales">Sales Partner</option><option value="team_lead">Team Lead</option></select></F>{m.role==="sales"&&<F l="Team Lead / vadītājs"><select value={m.parentId||"admin"} onChange={e=>set("parentId",e.target.value)}><option value="admin">Tieši zem Toma</option>{teamLeads.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></F>}<F l="Komisija par klientu (€)"><input type="number" min="0" value={m.payout} onChange={e=>set("payout",Number(e.target.value))}/></F>{m.role==="team_lead"&&<F l="Override par apakšpartnera klientu (€)"><input type="number" min="0" value={m.override} onChange={e=>set("override",Number(e.target.value))}/></F>}<F l="Konts"><select value={m.active?"active":"inactive"} onChange={e=>set("active",e.target.value==="active")}><option value="active">Aktīvs</option><option value="inactive">Bloķēts</option></select></F></div></div><div className="modalFoot"><button type="button" className="secondary" onClick={close}>Atcelt</button><button className="primary">{m.id?"Saglabāt":"Turpināt uz vienošanos"}</button></div></form></div>}
function AgreementModal({member,accept,close,gate,adminMode,onBack}){const[checked,setChecked]=useState(false),[typed,setTyped]=useState("");const valid=checked&&typed.trim().toLowerCase()===member.name.trim().toLowerCase();return <div className="overlay agreementOverlay"><div className="modal agreementModal"><div className="modalHead"><div><h2><LockKeyhole size={18}/> Sadarbības un konfidencialitātes vienošanās</h2><p>Versija {AGREEMENT_VERSION} · {member.name} · {roleName(member.role)}</p></div>{adminMode&&close&&<button type="button" onClick={close}><X/></button>}</div><div className="agreementScroll"><div className="agreementIntro">Pirms piekļuves klientu datiem ir jāiepazīstas ar noteikumiem un tie jāapstiprina.</div>{agreementSections.map(s=><section key={s.title}><h3>{s.title}</h3>{s.paragraphs.map((p,i)=><p key={i}>{p}</p>)}</section>)}</div><div className="agreementAccept"><button type="button" className="secondary" onClick={()=>printAgreement(member)}><Printer size={15}/>Drukāt papīra versiju</button><label className="checkLine"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/><span>Esmu izlasījis/-usi vienošanos, saprotu tās saturu un apņemos to ievērot.</span></label><label className="typedName"><span>Apstiprināšanai ieraksti savu vārdu un uzvārdu tieši kā norādīts:</span><b>{member.name}</b><input value={typed} onChange={e=>setTyped(e.target.value)} placeholder={member.name}/></label></div><div className="modalFoot">{gate&&onBack&&<button className="secondary" onClick={onBack}>Atpakaļ uz admin skatu</button>}{adminMode&&close&&<button className="secondary" onClick={close}>Vēlāk</button>}<button className="primary" disabled={!valid} onClick={()=>accept(member.id)}><ShieldCheck size={15}/>Apstiprināt vienošanos</button></div></div></div>}
function LeadModal({lead,setLead,members,isAdmin,save,close}){const[logType,setLogType]=useState("E-pasts"),[logNote,setLogNote]=useState(""),[adminComment,setAdminComment]=useState("");const readOnly=!isAdmin&&["READY FOR TOM","MEETING","INVOICE SENT","DEPOSIT PAID","IN DEVELOPMENT","WON"].includes(lead.status);const set=(k,v)=>setLead({...lead,[k]:v});const owner=members.find(m=>m.id===lead.ownerId),commission=lead.commission??owner?.payout??0;function addLog(){if(!logNote.trim())return;const d=new Date().toISOString().slice(0,10),x={id:crypto.randomUUID(),date:d,type:logType,note:logNote.trim()};setLead({...lead,contactLog:[x,...(lead.contactLog||[])],lastContact:d});setLogNote("")}function image(e){const f=e.target.files?.[0];if(!f||!f.type.startsWith("image/"))return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const max=1400,sc=Math.min(1,max/im.width),c=document.createElement("canvas");c.width=Math.round(im.width*sc);c.height=Math.round(im.height*sc);c.getContext("2d").drawImage(im,0,0,c.width,c.height);set("mockupImage",c.toDataURL("image/jpeg",.76))};im.src=r.result};r.readAsDataURL(f)}return <div className="overlay"><form className="modal" onSubmit={save}><div className="modalHead"><div><h2>{lead.id?lead.company:"Jauns klients"}</h2><p>Klienta dati, mockup, saziņas vēsture un atlīdzība.</p></div><button type="button" onClick={close}><X/></button></div><div className="modalBody"><div className="form"><F l="Uzņēmums"><input required value={lead.company} onChange={e=>set("company",e.target.value)}/></F><F l="Nozare"><select value={lead.industry} onChange={e=>set("industry",e.target.value)}>{industries.map(x=><option key={x}>{x}</option>)}</select></F><F l="Pilsēta"><input value={lead.city} onChange={e=>set("city",e.target.value)}/></F><F l="Lead score"><input type="number" min="0" max="100" value={lead.score} onChange={e=>set("score",Number(e.target.value))}/></F><F l="E-pasts"><input value={lead.email} onChange={e=>set("email",e.target.value)}/></F><F l="Telefons"><input value={lead.phone} onChange={e=>set("phone",e.target.value)}/></F><F l="Mājaslapa"><input value={lead.website} onChange={e=>set("website",e.target.value)}/></F><F l="Statuss"><select disabled={readOnly} value={lead.status} onChange={e=>set("status",e.target.value)}>{(isAdmin?statuses:Array.from(new Set(["NEW","MOCKUP READY","CONTACTED","REPLIED","INTERESTED","READY FOR TOM","LOST",lead.status]))).map(s=><option key={s} value={s}>{labels[s]||s}</option>)}</select></F><F l="Darījuma vērtība (€)"><input type="number" value={lead.value} onChange={e=>set("value",Number(e.target.value))}/></F><F l="Atbildīgais"><select disabled={!isAdmin} value={lead.ownerId} onChange={e=>set("ownerId",e.target.value)}>{members.filter(m=>m.role!=="admin"&&m.active).map(m=><option key={m.id} value={m.id}>{m.name} · {roleName(m.role)}</option>)}</select></F><F l="Nākamais follow-up"><input type="date" value={lead.nextFollowUp||""} onChange={e=>set("nextFollowUp",e.target.value)}/></F>{isAdmin&&<F l="Individuālā komisija (€)"><input type="number" placeholder={String(owner?.payout||0)} value={lead.commission??""} onChange={e=>set("commission",e.target.value===""?null:Number(e.target.value))}/></F>}{isAdmin&&<F l="Komisijas statuss"><select value={lead.commissionPaid?"paid":"pending"} onChange={e=>set("commissionPaid",e.target.value==="paid")}><option value="pending">Gaida izmaksu</option><option value="paid">Izmaksāts</option></select></F>}<div className="wide"><F l="Piezīmes"><textarea disabled={readOnly} rows="4" value={lead.notes} onChange={e=>set("notes",e.target.value)}/></F></div><div className="wide"><F l="Handoff kopsavilkums Tomam"><textarea disabled={readOnly} rows="3" value={lead.handoffSummary||""} onChange={e=>set("handoffSummary",e.target.value)} placeholder="Ko klients grib, svarīgākās prasības, budžeta/cenas konteksts..."/></F></div><div className="wide"><F l="Ko klientam esi apsolījis"><textarea disabled={readOnly} rows="2" value={lead.promises||""} onChange={e=>set("promises",e.target.value)} placeholder="Ja neko papildus: Nekas papildus nav solīts"/></F></div></div><section className="block"><div className="blockTitle"><FileImage size={18}/><div><b>Nosūtītais mockup</b><small>Bilde, ko nosūtīji klientam.</small></div></div>{lead.mockupImage?<div className="mock"><img src={lead.mockupImage}/><button type="button" className="secondary" onClick={()=>set("mockupImage","")}>Noņemt</button></div>:<label className="uploadZone"><ImageIcon size={25}/><b>Pievienot mockup bildi</b><small>PNG/JPG, attēls tiks samazināts glabāšanai.</small><input hidden type="file" accept="image/*" onChange={image}/></label>}</section><section className="block"><div className="blockTitle"><MessageSquareText size={18}/><div><b>Saziņas vēsture</b><small>E-pasti, zvani un Google Meet.</small></div></div><div className="log"><select value={logType} onChange={e=>setLogType(e.target.value)}><option>E-pasts</option><option>Zvans</option><option>Google Meet</option><option>Follow-up</option><option>Cits</option></select><input value={logNote} onChange={e=>setLogNote(e.target.value)} placeholder="Ko klients pateica?"/><button type="button" className="secondary" onClick={addLog}><Plus size={14}/>Pievienot</button></div><div className="timeline">{(lead.contactLog||[]).map(x=><div className="event" key={x.id}><i/><div><b>{x.type}<span>{x.date}</span></b><p>{x.note}</p></div></div>)}</div></section><section className="block"><div className="blockTitle"><MessageSquareText size={18}/><div><b>Admin komentāri</b><small>Norādes un piezīmes konkrētajam partnerim.</small></div></div>{(lead.adminComments||[]).map(c=><div className="adminComment" key={c.id}><b>Admin</b><p>{c.body}</p><small>{new Date(c.at).toLocaleString("lv-LV")}</small></div>)}{isAdmin&&<div className="log"><input value={adminComment} onChange={e=>setAdminComment(e.target.value)} placeholder="Uzraksti komentāru partnerim..."/><button type="button" className="secondary" onClick={()=>{if(!adminComment.trim())return;setLead({...lead,adminComments:[...(lead.adminComments||[]),{id:crypto.randomUUID(),body:adminComment.trim(),at:now()}]});setAdminComment("")}}><Plus size={14}/>Pievienot</button></div>}</section><div className="commission"><Wallet size={18}/><div><small>Partnera komisija par šo klientu</small><b>€{commission}</b></div><span>{payoutStatuses.includes(lead.status)?(lead.commissionPaid?"Izmaksāts":"Nopelnīts · gaida izmaksu"):"Tiks ieskaitīts pēc priekšapmaksas"}</span></div></div><div className="modalFoot"><button type="button" className="secondary" onClick={close}>Atcelt</button><button className="primary">Saglabāt klientu</button></div></form></div>}
function F({l,children}){return <label className="field"><span>{l}</span>{children}</label>}
function SetupScreen({onCreated}){
 const[name,setName]=useState("Toms"),[email,setEmail]=useState(""),[password,setPassword]=useState(""),[confirmPassword,setConfirmPassword]=useState(""),[error,setError]=useState(""),[loading,setLoading]=useState(false);
 async function submit(e){
  e.preventDefault();
  setError("");
  if(password!==confirmPassword)return setError("Paroles nesakrīt");
  if(password.length<10)return setError("Parolei jābūt vismaz 10 simbolus garai");
  setLoading(true);
  try{
   const d=await api.createFirstAdmin({name,email,password});
   onCreated(d.user);
  }catch(err){setError(err.message)}
  finally{setLoading(false)}
 }
 return <div className="loginPage"><form className="loginCard setupCard" onSubmit={submit}>
  <div className="loginBrand"><div className="mark">T</div><div><b>Tagorit</b><small>Pirmā palaišana</small></div></div>
  <div className="setupBadge"><ShieldCheck size={14}/>Sistēmā vēl nav admina</div>
  <h1>Izveido pirmo adminu</h1>
  <p>Šis ekrāns ir pieejams tikai līdz pirmā admin konta izveidei. Pēc tam tas automātiski aizslēgsies.</p>
  <F l="Vārds, uzvārds"><input required value={name} onChange={e=>setName(e.target.value)} autoComplete="name"/></F>
  <F l="Admin e-pasts"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email"/></F>
  <F l="Parole"><input type="password" required minLength="10" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password"/></F>
  <F l="Atkārto paroli"><input type="password" required minLength="10" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} autoComplete="new-password"/></F>
  <div className="passwordHint">Izmanto vismaz 10 simbolus un neizmanto šo paroli citur.</div>
  {error&&<div className="loginError">{error}</div>}
  <button className="primary loginButton" disabled={loading}>{loading?"Izveido kontu...":"Izveidot admin kontu"}</button>
 </form></div>
}

function LoginScreen({onLogin}){
 const[email,setEmail]=useState(""),[password,setPassword]=useState(""),[error,setError]=useState(""),[loading,setLoading]=useState(false);
 async function submit(e){e.preventDefault();setLoading(true);setError("");try{const d=await api.login(email,password);onLogin(d.user)}catch(err){setError(err.message)}finally{setLoading(false)}}
 return <div className="loginPage"><form className="loginCard" onSubmit={submit}><div className="loginBrand"><div className="mark">T</div><div><b>Tagorit</b><small>Sales network</small></div></div><h1>Ielogoties</h1><p>Ievadi savu darba kontu, lai turpinātu.</p><F l="E-pasts"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email"/></F><F l="Parole"><input type="password" required value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></F>{error&&<div className="loginError">{error}</div>}<button className="primary loginButton" disabled={loading}>{loading?"Pieslēdzas...":"Ielogoties"}</button></form></div>
}
function Root(){
 const[user,setUser]=useState(null),[loading,setLoading]=useState(true),[needsSetup,setNeedsSetup]=useState(false),[bootError,setBootError]=useState("");
 useEffect(()=>{let alive=true;(async()=>{try{
   const setup=await api.setupStatus();
   if(!alive)return;
   if(setup.needsSetup){setNeedsSetup(true);setLoading(false);return}
   try{const d=await api.me();if(alive)setUser(d.user)}catch{if(alive)setUser(null)}
  }catch(err){if(alive)setBootError(err.message)}
  finally{if(alive)setLoading(false)}})();return()=>{alive=false}},[]);
 async function logout(){try{await api.logout()}finally{setUser(null)}}
 function created(firstAdmin){setNeedsSetup(false);setUser(firstAdmin)}
 if(loading)return <div className="appLoading"><div className="mark">T</div><b>Pārbauda sistēmu...</b></div>;
 if(bootError)return <div className="fatal"><h2>Tagorit setup nevar startēt</h2><p>{bootError}</p><p>Pārbaudi Vercel DATABASE_URL un vai Neon datubāzē ir palaists db/schema.sql.</p></div>;
 if(needsSetup)return <SetupScreen onCreated={created}/>;
 if(!user)return <LoginScreen onLogin={setUser}/>;
 return <App sessionUser={user} onLogout={logout}/>;
}
createRoot(document.getElementById("root")).render(<Root/>);
